#!/usr/bin/env bash
set -u
cd /home/w421/w421/calaire-stat || exit 1
mkdir -p curso/citas
for spec in 'S1_fundamentos' 'S2_modelos_calibracion' 'S3_comparacion_decision' 'S4_numericos_integracion'; do
  sec=${spec%%_*}
  prompt="Eres luna, ejecutor del cotejo bibliográfico. Lee curso/guia_libreto.md y curso/revision_final.md. Trabaja SOLO el lote curso/$spec/*_libreto.md (MXX y AX, no auditorias). No commits. No cambies contenido docente salvo correcciones de citas necesarias. Inventaría TODAS las ocurrencias de citas y claves bibliográficas del lote, con archivo, línea, clave original/canónica, ubicación citada y referencia completa, en curso/citas/${sec}_inventario.md; crea/actualiza curso/citas/inventario.md como índice acumulativo a los inventarios detallados y catálogo común de claves. Coteja cada cita con docs/ y fuentes abiertas verificables: edición, numeral y página si consta; nunca inventes páginas ni deduzcas verificación solo del título. Conserva distinción entre ausencia en docs/ y verificación externa. Escribe curso/citas/${sec}_cotejo.md con cada cita inventariada, estado verificada/corregida/no verificable, evidencia exacta (archivo y numeral/página o URL consultada con pasaje y fecha), motivo para toda no verificable. Verificar referencia y soporte de afirmación, no solo existencia del documento. Si fuente inaccesible, no verificable explícita, sin inventar. Unifica claves entre capítulos leyendo catálogo y otros libretos como consulta; Montgomery debe ser Montgomery 2013 solo cuando corresponda realmente a esa edición; atiende H-02 de O-02 en AX y M11. Registra cambios en curso/citas/${sec}_decisiones_luna.md. No toques otros pendientes ni logs de otros supervisores. Fuentes descargadas en directorio nuevo vacío independiente, scripts separados; Python con -I. El curso es estadística para operadores del SRP laboratorio designado INM, aplicado ozono, fase contenido. Ejecuta el trabajo, no solo plan."
  claude-luna --effort low -p --dangerously-skip-permissions --output-format text "$prompt" > "curso/logs/citas_${sec}_luna.out" 2>&1 || exit $?
  env -u ANTHROPIC_BASE_URL -u ANTHROPIC_API_KEY -u CLAUDE_CODE_AUTO_MODE_SERVER claude --model claude-haiku-5-5 --effort low -p --dangerously-skip-permissions --output-format text "Revisa el lote bibliográfico $sec en /home/w421/w421/calaire-stat. Lee curso/guia_libreto.md, curso/citas/${sec}_inventario.md, ${sec}_cotejo.md, ${sec}_decisiones_luna.md y los libretos curso/$spec/*_libreto.md. Comprueba exhaustividad del inventario, claves coherentes con otros capítulos, evidencia real de edición/numeral/página y soporte de afirmaciones. Contrasta docs/ o fuentes abiertas cuando sea necesario; jamás inventes páginas. No edites libretos ni inventarios ni cotejos. Escribe SOLO curso/citas/${sec}_revision_haiku.md con hallazgos H-xx, archivo/línea, evidencia, gravedad y corrección propuesta; distingue limitaciones aceptables de defectos. Si no hay hallazgos di explícitamente ninguno. No commits." > "curso/logs/citas_${sec}_haiku.out" 2>&1 || exit $?
  claude-luna --effort low -p --dangerously-skip-permissions --output-format text "Aplica revisión de curso/citas/${sec}_revision_haiku.md al lote curso/$spec/*_libreto.md y archivos curso/citas/${sec}_*.md. Lee guía. Para CADA H-xx aplica o rechaza con justificación y evidencia en curso/citas/${sec}_decisiones_luna.md. Actualiza inventario y cotejo tras cambios y catálogo curso/citas/inventario.md. No inventes páginas ni afirmes verificado sin evidencia consultada. No edites revisión Haiku. No commits ni otros pendientes. Ejecuta ajustes reales." > "curso/logs/citas_${sec}_ajustes.out" 2>&1 || exit $?
done
